"""Shared ``@skill`` / ``@block`` / ``@tool`` token patterns for skill.md prose."""

from __future__ import annotations

import re

# One-segment tokens; extra path segments are incomplete lookalikes.
COMPLETE_PROSE_TOOL_REF_PATTERN = re.compile(
    r"(?<![\w])@tool\.([\w-]+)(?![\w-])(?!\.[\w-])"
)
INCOMPLETE_PROSE_TOOL_LOOKALIKE_PATTERN = re.compile(
    r"(?<![\w])@tool(?:\.[\w-]+)*(?![\w-])"
)


def collect_complete_prose_tool_reference_names(prose: str) -> list[str]:
    """Return unique ``@tool.<name>`` names in *prose* (first-seen order)."""
    seen: set[str] = set()
    names: list[str] = []
    for match in COMPLETE_PROSE_TOOL_REF_PATTERN.finditer(prose):
        name = match.group(1)
        if name in seen:
            continue
        seen.add(name)
        names.append(name)
    return names
